<template>
  <div class="page-shell"><NavBar /><main v-if="user" class="profile-page"><PageColumns>
    <section class="profile-hero surface">
      <div class="cover" :style="coverStyle"><div class="cover-pattern"></div><label v-if="isMe&&user.recovery_status!=='pending'" class="upload">Change header<input type="file" hidden accept="image/*" @change="upload($event, 'header')" /></label></div>
      <div class="profile-row"><div class="portrait"><img v-if="user.profile_image_url" :src="user.profile_image_url" alt="Profile picture" /><span v-else>{{ initials }}</span><label v-if="isMe&&user.recovery_status!=='pending'" class="camera"><span aria-hidden="true">+</span><span class="sr-only">Change profile picture</span><input type="file" hidden accept="image/*" @change="upload($event, 'profile')" /></label></div><div class="identity"><span class="eyebrow">Blugger profile</span><h1>{{ user.full_name }}</h1><p>@{{ user.chatter_name }}</p><small v-if="isMe&&user.recovery_status==='pending'">Pending approval</small></div><button v-if="!isMe" class="primary-button" @click="toggleFollow">{{ status.following ? 'Following' : 'Follow' }}</button><button v-else class="ghost-button" @click="router.push('/settings')">Edit profile</button></div>
      <div class="profile-bottom"><p>{{ user.about_me || 'Writing thoughts, finding people, starting conversations.' }}</p><div><b>{{ posts.length }}</b><span>Blugs</span><b>{{ status.followers }}</b><span>Followers</span><b>{{ status.followingCount }}</b><span>Following</span></div></div>
    </section>
    <div class="profile-content"><section><div class="section-head"><div><span class="eyebrow">Published work</span><h2>Latest blugs</h2></div><button v-if="isMe" class="primary-button" @click="router.push('/create-blog')">＋ New blug</button></div><LocalPostCard v-for="post in posts" :key="post.id" :post="post" /></section></div>
    <template #right><aside class="surface profile-about"><span class="eyebrow">About this voice</span><h3>Interests</h3><div class="chips"><span v-for="topic in topics" :key="topic">{{ topic }}</span></div><hr /><p class="muted">Member since {{ new Date(user.created_at).toLocaleDateString('en', { month: 'long', year: 'numeric' }) }}</p></aside></template>
  </PageColumns></main></div>
</template>
<script setup lang="ts">
import PageColumns from './PageColumns.vue';
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import NavBar from './NavBar.vue'; import LocalPostCard from './LocalPostCard.vue'; import { getUser } from '../api/users'; import { listPosts } from '../api/posts'; import { getFollowStatus, setFollowing } from '../api/social'; import { uploadImage } from '../api/uploads'; import { authStore } from '../stores/auth'; import type { LocalUser, LocalPost } from '../api/types';
const route=useRoute(),router=useRouter(),user=ref<LocalUser|null>(null),posts=ref<LocalPost[]>([]),status=reactive({following:false,followers:0,followingCount:0}); const isMe=computed(()=>user.value?.id===authStore.user.value?.id),initials=computed(()=>(user.value?.full_name||'BB').split(' ').map(x=>x[0]).slice(0,2).join('')),coverStyle=computed(()=>user.value?.header_image_url?{backgroundImage:`linear-gradient(0deg,rgba(10,12,15,.35),transparent),url(${user.value.header_image_url})`}:{}),topics=computed(()=>[...new Set(posts.value.map(p=>p.categories).filter(Boolean))].slice(0,6)); const load=async()=>{const id=String(route.params.userId);user.value=(await getUser(id)).user;posts.value=(await listPosts(id)).posts;Object.assign(status,await getFollowStatus(id))}; const toggleFollow=async()=>{if(!user.value)return;await setFollowing(user.value.id,!status.following);await load()}; const upload=async(e:Event,purpose:'profile'|'header')=>{const input=e.target as HTMLInputElement;const file=input.files?.[0];if(file){const {url}=await uploadImage(file,purpose);if(user.value)user.value={...user.value,[purpose==='header'?'header_image_url':'profile_image_url']:url};await authStore.refresh();await load();input.value=''}}; onMounted(load);
</script>
