end;margin-bottom:18px}.section-head h2{font:700 2rem Georgia;margin:6px 0 0}.profile-content aside{align-self:start;padding:22px}.profile-content aside h3{margin:8px 0 12px;font:700 1.15rem/1.2 Georgia,serif}.chips{display:flex;flex-wrap:wrap;gap:7px}.chips span{padding:7px 10px;border:1px solid var(--line);border-radius:99px;background:var(--soft);color:var(--text);font-size:.76rem}.profile-content hr{border:0;border-top:1px solid var(--line);margin:20px 0}
