@media(max-width:520px){.profile-page{width:100%;padding:0 0 88px}.profile-hero{border-left:0;border-right:0;border-radius:0}.cover{height:126px}.upload{right:12px;bottom:10px;padding:7px 10px;font-size:.65rem}.profile-row{display:grid;grid-template-columns:82px minmax(0,1fr);grid-template-rows:auto auto;align-items:end;column-gap:14px;row-gap:7px;padding:0 16px 14px;transform:none;margin:0}.portrait{grid-column:1;grid-row:1/3;align-self:start;flex-basis:auto;width:82px;height:82px;margin-top:-34px;border-width:4px}.camera{right:-2px;bottom:0;width:29px;height:29px;border-width:2px}.identity{grid-column:2;grid-row:1;min-width:0;padding:10px 0 0;margin:0}.identity .eyebrow{font-size:.58rem}.identity h1{margin:4px 0 1px;font-size:1.48rem;line-height:1.05;overflow-wrap:anywhere}.identity p{font-size:.78rem}.profile-row>button{grid-column:2;grid-row:2;align-self:start;justify-self:start;margin:0;padding:7px 11px;font-size:.67rem}.profile-bottom{display:block;padding:0 16px 18px}.profile-bottom>p{margin:0 0 14px;font-size:.83rem;line-height:1.45}.profile-bottom>div{display:grid;grid-template-columns:repeat(3,1fr);gap:2px 12px;padding-top:12px;border-top:1px solid var(--line)}.profile-bottom b{grid-row:1;font-size:1rem}.profile-bottom span{grid-row:2;font-size:.65rem}.profile-bottom b:nth-of-type(1),.profile-bottom span:nth-of-type(1){grid-column:1}.profile-bottom b:nth-of-type(2),.profile-bottom span:nth-of-type(2){grid-column:2}.profile-bottom b:nth-of-type(3),.profile-bottom span:nth-of-type(3){grid-column:3}.profile-content{margin-top:0}.section-head{align-items:center;padding:18px 14px 10px;margin:0}.section-head .eyebrow{font-size:.58rem}.section-head h2{margin-top:4px;font-size:1.55rem;line-height:1}.section-head .primary-button{padding:8px 11px;font-size:.7rem;white-space:nowrap}}
